-- ============================================================
-- SAN MIGUEL, BULACAN -- legacy business roster import
-- ============================================================
-- Source: reference/legacy-data/BPLO_LBT_Backfill_v2.csv, filtered to
-- bt_source = 'actual' only (1177 of 1350 rows).
--
-- Deliberately EXCLUDED, not imported by this script:
--   - bt_source = 'needs_review' (168 rows, matches BPLO_LBT_NeedsReview.csv
--     exactly) -- flagged by whoever produced this export as needing manual
--     review before import, per reference/legacy-data/README.md.
--   - bt_source = 'no_match' (5 rows) -- blank License No., meaning these
--     businesses have no bridge key at all and can't be reached by the
--     legacy-claim flow's License Number lookup (CLAUDE.md section 5).
--     Real businesses, just not importable via this mechanism as-is.
--
-- All rows: is_legacy_unclaimed=true, owner_id=null, is_active=true.
-- gross_sales_history seeded with only one year (2026) since this export
-- is a single-year snapshot, not multi-year history.
--
-- Requires migration 0005 (businesses.legacy_owner_name) to be applied.
-- Safe to re-run: deletes San Miguel's legacy-unclaimed businesses first.

delete from businesses where lgu_id = (select id from lgus where name = 'San Miguel') and is_legacy_unclaimed = true;

